import http.server,subprocess,json
class H(http.server.BaseHTTPRequestHandler):
 def do_GET(self):
  d=json.loads(subprocess.check_output(["curl","-sL","https://api.thaistock2d.com/live"]))
  rows="".join("<div style=\"display:flex;justify-content:space-between;padding:14px;border-bottom:1px solid #351313\"><span>"+x["stock_date"]+" "+x["open_time"]+"</span><b style=\"color:#ff3030;font-size:22px\">"+x["twod"]+"</b></div>" for x in reversed(d["result"]))
  html="<!doctype html><html><head><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta http-equiv=\"refresh\" content=\"10\"><title>2D LIVE</title><style>body{margin:0;background:#050505;color:#fff;font-family:-apple-system;padding:20px}.box{background:#120707;border:1px solid #351313;border-radius:18px;padding:20px;margin-bottom:15px}.title{text-align:center;color:#ff3030;font-size:28px;font-weight:800}.live{text-align:center;font-size:64px;font-weight:900;margin:15px;color:#fff}.label{color:#b88b8b;text-align:center}.num{text-align:center;font-size:25px;font-weight:700;margin:6px}</style></head><body><div class=\"box\"><div class=\"title\">2D LIVE</div><div class=\"label\">"+d["live"]["date"]+"</div><div class=\"live\">"+d["live"]["twod"]+"</div><div class=\"label\">"+("LIVE" if d["live"]["twod"]!="--" else "CLOSED")+"</div></div><div class=\"box\"><div class=\"label\">SET</div><div class=\"num\">"+d["live"]["set"]+"</div><div class=\"label\">VALUE</div><div class=\"num\">"+d["live"]["value"]+"</div></div><div class=\"box\"><div class=\"title\" style=\"font-size:20px\">HISTORY</div>"+rows+"</div></body></html>"
  self.send_response(200);self.send_header("Content-Type","text/html");self.end_headers();self.wfile.write(html.encode())
http.server.HTTPServer(("0.0.0.0",8080),H).serve_forever()
